/**
 * DropKit Interactive Canvas Chart Engine
 * Lightweight, zero-dependency, self-contained interactive chart engine
 * Supports: Line charts with gradients, Bar charts with rounded corners, and Doughnut charts
 */
(function(window) {
  class DropKitChart {
    constructor(canvas, config) {
      this.canvas = typeof canvas === 'string' ? document.getElementById(canvas) : canvas;
      if (!this.canvas) return;
      this.ctx = this.canvas.getContext('2d');
      this.config = config || {};
      this.type = this.config.type || 'line';
      this.data = this.config.data || {};
      this.options = this.config.options || {};
      
      this.init();
    }

    init() {
      // Responsive high-DPI scaling
      const rect = this.canvas.getBoundingClientRect();
      const dpr = window.devicePixelRatio || 1;
      this.width = rect.width || this.canvas.width || 400;
      this.height = rect.height || this.canvas.height || 220;
      
      this.canvas.width = this.width * dpr;
      this.canvas.height = this.height * dpr;
      this.ctx.scale(dpr, dpr);

      this.render();
    }

    render() {
      this.ctx.clearRect(0, 0, this.width, this.height);
      if (this.type === 'line') {
        this.renderLineChart();
      } else if (this.type === 'bar') {
        this.renderBarChart();
      } else if (this.type === 'doughnut') {
        this.renderDoughnutChart();
      }
    }

    renderLineChart() {
      const { labels, datasets } = this.data;
      if (!labels || !datasets || datasets.length === 0) return;

      const padding = { top: 20, right: 20, bottom: 35, left: 45 };
      const chartW = this.width - padding.left - padding.right;
      const chartH = this.height - padding.top - padding.bottom;

      // Find max value across datasets
      let maxVal = 0;
      datasets.forEach(ds => {
        ds.data.forEach(v => { if (v > maxVal) maxVal = v; });
      });
      maxVal = maxVal === 0 ? 10 : Math.ceil(maxVal * 1.15);

      // Draw grid lines
      this.ctx.strokeStyle = '#E5E7EB';
      this.ctx.lineWidth = 1;
      this.ctx.font = '11px sans-serif';
      this.ctx.fillStyle = '#74778D';
      this.ctx.textAlign = 'right';

      const gridSteps = 4;
      for (let i = 0; i <= gridSteps; i++) {
        const y = padding.top + (chartH / gridSteps) * i;
        const val = Math.round(maxVal - (maxVal / gridSteps) * i);
        this.ctx.beginPath();
        this.ctx.moveTo(padding.left, y);
        this.ctx.lineTo(this.width - padding.right, y);
        this.ctx.stroke();
        this.ctx.fillText(val >= 1000 ? (val/1000).toFixed(1) + 'k' : val, padding.left - 8, y + 4);
      }

      // Draw X labels
      this.ctx.textAlign = 'center';
      const stepX = chartW / Math.max(1, labels.length - 1);
      const labelInterval = labels.length > 15 ? Math.ceil(labels.length / 8) : 1;
      labels.forEach((lbl, idx) => {
        if (idx % labelInterval === 0 || idx === labels.length - 1) {
          const x = padding.left + idx * stepX;
          this.ctx.fillText(lbl, x, this.height - 10);
        }
      });

      // Plot datasets
      datasets.forEach(ds => {
        const color = ds.borderColor || '#FF653D';
        const fillGradient = ds.fill ? (this.ctx.createLinearGradient(0, padding.top, 0, this.height - padding.bottom)) : null;
        if (fillGradient) {
          fillGradient.addColorStop(0, ds.backgroundColor || 'rgba(255, 101, 61, 0.25)');
          fillGradient.addColorStop(1, 'rgba(255, 101, 61, 0.0)');
        }

        const points = ds.data.map((val, idx) => {
          const x = padding.left + idx * stepX;
          const y = padding.top + chartH - (val / maxVal) * chartH;
          return { x, y };
        });

        // Fill area
        if (fillGradient && points.length > 0) {
          this.ctx.beginPath();
          this.ctx.moveTo(points[0].x, padding.top + chartH);
          points.forEach(p => this.ctx.lineTo(p.x, p.y));
          this.ctx.lineTo(points[points.length - 1].x, padding.top + chartH);
          this.ctx.closePath();
          this.ctx.fillStyle = fillGradient;
          this.ctx.fill();
        }

        // Draw line
        this.ctx.beginPath();
        this.ctx.strokeStyle = color;
        this.ctx.lineWidth = ds.borderWidth || 2.5;
        this.ctx.lineJoin = 'round';
        points.forEach((p, idx) => {
          if (idx === 0) this.ctx.moveTo(p.x, p.y);
          else this.ctx.lineTo(p.x, p.y);
        });
        this.ctx.stroke();

        // Draw points
        this.ctx.fillStyle = color;
        points.forEach((p, idx) => {
          if (labels.length <= 20 || idx % 2 === 0) {
            this.ctx.beginPath();
            this.ctx.arc(p.x, p.y, 3.5, 0, Math.PI * 2);
            this.ctx.fill();
            this.ctx.fillStyle = '#FFFFFF';
            this.ctx.beginPath();
            this.ctx.arc(p.x, p.y, 1.8, 0, Math.PI * 2);
            this.ctx.fill();
            this.ctx.fillStyle = color;
          }
        });
      });
    }

    renderBarChart() {
      const { labels, datasets } = this.data;
      if (!labels || !datasets || datasets.length === 0) return;

      const padding = { top: 20, right: 20, bottom: 35, left: 45 };
      const chartW = this.width - padding.left - padding.right;
      const chartH = this.height - padding.top - padding.bottom;

      let maxVal = 0;
      datasets.forEach(ds => {
        ds.data.forEach(v => { if (v > maxVal) maxVal = v; });
      });
      maxVal = maxVal === 0 ? 10 : Math.ceil(maxVal * 1.15);

      // Grid
      this.ctx.strokeStyle = '#E5E7EB';
      this.ctx.lineWidth = 1;
      this.ctx.font = '11px sans-serif';
      this.ctx.fillStyle = '#74778D';
      this.ctx.textAlign = 'right';

      const gridSteps = 4;
      for (let i = 0; i <= gridSteps; i++) {
        const y = padding.top + (chartH / gridSteps) * i;
        const val = Math.round(maxVal - (maxVal / gridSteps) * i);
        this.ctx.beginPath();
        this.ctx.moveTo(padding.left, y);
        this.ctx.lineTo(this.width - padding.right, y);
        this.ctx.stroke();
        this.ctx.fillText(val >= 1000 ? (val/1000).toFixed(1) + 'k' : val, padding.left - 8, y + 4);
      }

      // Bars
      const numBars = labels.length;
      const barSlot = chartW / numBars;
      const barWidth = Math.min(28, barSlot * 0.65);

      labels.forEach((lbl, idx) => {
        const x = padding.left + idx * barSlot + (barSlot - barWidth) / 2;
        const val = datasets[0].data[idx] || 0;
        const bHeight = (val / maxVal) * chartH;
        const y = padding.top + chartH - bHeight;

        // Draw bar with rounded top
        this.ctx.fillStyle = datasets[0].backgroundColor || '#FF653D';
        this.ctx.beginPath();
        this.ctx.roundRect(x, y, barWidth, bHeight, [4, 4, 0, 0]);
        this.ctx.fill();

        // Label
        if (numBars <= 15 || idx % Math.ceil(numBars / 8) === 0) {
          this.ctx.textAlign = 'center';
          this.ctx.fillStyle = '#74778D';
          this.ctx.fillText(lbl, x + barWidth / 2, this.height - 10);
        }
      });
    }

    renderDoughnutChart() {
      const { labels, datasets } = this.data;
      if (!datasets || datasets.length === 0) return;

      const data = datasets[0].data;
      const colors = datasets[0].backgroundColor || ['#FF653D', '#1B1D3B', '#10B981', '#F59E0B'];
      const total = data.reduce((a, b) => a + b, 0);

      const centerX = this.width / 2;
      const centerY = this.height / 2;
      const outerRadius = Math.min(centerX, centerY) - 20;
      const innerRadius = outerRadius * 0.62;

      let startAngle = -Math.PI / 2;
      data.forEach((val, idx) => {
        const sliceAngle = (val / total) * Math.PI * 2;
        this.ctx.beginPath();
        this.ctx.arc(centerX, centerY, outerRadius, startAngle, startAngle + sliceAngle);
        this.ctx.arc(centerX, centerY, innerRadius, startAngle + sliceAngle, startAngle, true);
        this.ctx.closePath();
        this.ctx.fillStyle = colors[idx % colors.length];
        this.ctx.fill();
        startAngle += sliceAngle;
      });

      // Center hole
      this.ctx.fillStyle = this.options.holeColor || (document.documentElement.getAttribute('data-theme') === 'dark' ? '#161828' : '#FFFFFF');
      this.ctx.beginPath();
      this.ctx.arc(centerX, centerY, innerRadius - 2, 0, Math.PI * 2);
      this.ctx.fill();
    }

    update(newData) {
      if (newData) this.data = newData;
      this.init();
    }
  }

  window.DropKitChart = DropKitChart;
})(window);
